(function(){'use strict';
const hub=document.getElementById('g-session-hub'),W=window.NavigatorWorkflowSession,T=window.NavigatorTimelineUI;
if(!hub||!W||!T)return;
const MAX_BYTES=2000000,$=id=>document.getElementById(id);
hub.innerHTML=`<div class="session-heading"><div><span class="g-label">Your private workspace</span><h2>Save and resume</h2><p>Keep a verified local recovery file to resume your work.</p></div><div class="g-button-row"><button class="g-btn" id="session-save" type="button">Save recovery file</button><button class="g-btn secondary" id="session-restore-open" type="button">Resume from a file</button></div></div><p id="session-save-status" class="g-mini" role="status"></p><details id="session-workspace-options"><summary>Recovery, onboarding and handover options</summary><details id="session-auto-options"><summary>Optional local file updates</summary><label class="session-auto"><input id="session-auto-save" type="checkbox" disabled> Keep my chosen local recovery file updated while this tab is open</label><p id="session-auto-help" class="g-mini">Optional: available after a native Save and read-back check. No case information goes to a server. Keep this tab open until all changes are verified.</p></details><details id="session-file-options"><summary>Alternative download and saved-file check</summary><p>If the Save dialog is unavailable, download a file, then select it below to check that it is usable before closing this tab.</p><button class="g-btn secondary" id="session-download" type="button">Use browser download</button><a class="g-btn secondary" id="session-download-link" hidden>Download recovery file again</a><label for="session-verify-file">Check the saved recovery file</label><input id="session-verify-file" type="file" accept=".json,application/json"><p>Files are read locally, never uploaded. A download request alone is not confirmation that a file was saved.</p></details><details id="session-onboarding"><summary>New here? Your first three steps</summary><ol class="session-onboarding"><li><strong>Keep identities outside Navigator.</strong> Use codes and retain official signed records in your institution’s secure system.</li><li><strong>Work on the current step.</strong> Prepare relevant drafts and record verified dates. The Committee authorises every action.</li><li><strong>Save and check before leaving.</strong> Choose a secure file location. Wait for Saved and verified, or check the browser download using the file selector above. Resume from that file next time.</li></ol><p>Recovery includes the evidence/annexure index, its review history, and unfinished form fields as drafts only. It does not include downloaded Word files, selected evidence files or unrecorded testimony. Keep the recovery file securely; it is readable JSON.</p><button class="g-btn secondary" id="session-ready" type="button">Ready — go to current step</button></details><details id="session-review-panel"><summary>Session review and handover</summary><p>Review outstanding dates, responsible roles and draft requests. This sheet is separate from your recovery file and does not complete a legal step.</p><div class="g-button-row"><button id="session-review-refresh" class="g-btn secondary" type="button">Review current session</button><button id="session-review-dates" class="g-btn secondary" type="button">Review timeline and follow-ups</button><button id="session-review-download" class="g-btn secondary" type="button">Download printable review sheet</button></div><div id="session-review-content"></div></details></details><section id="session-restore-panel" class="session-restore" hidden><h3>Restore a local recovery file</h3><label for="session-file">Choose a Navigator JSON export</label><input id="session-file" type="file" accept=".json,application/json"><p>Files are read in this tab, never uploaded. Imported history is untrusted; verify it against source records. Unsubmitted entries remain drafts and do not record a legal milestone.</p><p id="session-restore-preview" role="status"></p><button id="session-restore-confirm" class="g-btn" type="button" hidden>Replace this tab with the reviewed file</button><button id="session-restore-cancel" class="g-btn secondary" type="button">Cancel restore</button></section><p id="session-error" class="g-alert" role="alert" hidden></p><section id="session-replace-panel" class="g-soft" aria-labelledby="session-replace-title" hidden><h3 id="session-replace-title" tabindex="-1">Replace workflow choices?</h3><p id="session-replace-description"></p><p>Save and verify a recovery file first if you need the current version. Timeline dates, evidence references and history stay unchanged. For a different case, save this work and open a fresh tab; do not mix records.</p><div class="g-button-row"><button id="session-replace-save" class="g-btn secondary" type="button">Save current session first</button><button id="session-replace-confirm" class="g-btn" type="button">Continue and replace workflow choices</button><button id="session-replace-cancel" class="g-btn secondary" type="button">Cancel — keep current work</button></div></section>`;
const badge=document.createElement('button');badge.id='session-save-badge';badge.type='button';badge.className='g-btn session-save-badge';badge.onclick=()=>save();document.getElementById('g-body').before(badge);
const toolbar=document.querySelector('.g-toolbar');if(toolbar)document.querySelector('.g-shell').append(toolbar);
const note=document.querySelector('.g-session-note');if(note)note.textContent='Use participant codes; keep original case records with your institution.';
const formIds=['timeline-review','timeline-date','timeline-event'];
let saved='',verifiedName='',pending=null,restoreGeneration=0,downloadURL='',downloadRequested=false,busy=false,localHandle=null,lastFileText='',autoSaving=false;
function drafts(){return{forms:formIds.map(id=>({id,fields:[...$(id).elements].filter(e=>e.name&&['INPUT','SELECT'].includes(e.tagName)&&e.type!=='file').map(e=>({name:e.name,value:e.type==='checkbox'?e.checked:e.value}))})),documents:[...document.querySelectorAll('#g-body [id^="g-context-"]')].filter(e=>e.querySelector('[data-document-select]')).map(e=>({id:e.id,selection:e.querySelector('[data-document-select]').value,actor:e.querySelector('[data-document-actor]').value,reason:e.querySelector('[data-document-reason]').value}))};}
function snapshot(){return{format:'posh-navigator-session',schemaVersion:4,workflow:W.snapshot(),timeline:T.snapshot(),drafts:drafts(),evidence:window.NavigatorEvidenceUI.snapshot()};}
let baseline=JSON.stringify(snapshot());
function dirty(){return JSON.stringify(snapshot())!==(saved||baseline);}
function message(text,warning=true){$('session-error').hidden=false;$('session-error').className=warning?'g-alert':'g-soft';$('session-error').textContent=text;}
function status(){const changed=dirty();const review=$('session-review-content');if(review?.hasChildNodes()&&reviewSnapshot!==reviewKey()){review.replaceChildren();const note=document.createElement('p');note.textContent='Your session changed. Choose Review current session to refresh this summary.';review.append(note);reviewSnapshot=reviewKey();}const text=($('session-auto-save').checked?'Local file updates enabled while this tab is open. ':'')+(verifiedName?'Saved file checked: '+verifiedName+'. ':downloadRequested?'Download requested; saved copy not yet verified. ':'No automatic save. ')+(changed?'Changes in this tab still need a verified recovery file. Keep this tab open.':verifiedName?'You can close this tab and resume from the checked file.':'Choose Save recovery file before leaving.');if($('session-save-status').textContent!==text)$('session-save-status').textContent=text;const badge=$('session-save-badge');if(badge){badge.hidden=!changed;badge.textContent='Unsaved changes - save recovery file';}}
function stopAuto(forget=false){$('session-auto-save').checked=false;if(forget){localHandle=null;lastFileText='';$('session-auto-save').disabled=true;}}
function markSaved(value,name){saved=JSON.stringify(value);verifiedName=name;downloadRequested=false;status();}
function prepareDrafts(value,workflow,timeline,older=false){
 if(value===undefined)return()=>{for(const name of ['actor','reason'])$('timeline-review').elements.namedItem(name).value='';$('timeline-event').reset();$('timeline-date').elements.value.value='';for(const host of document.querySelectorAll('#g-body [id^="g-context-"]')){const select=host.querySelector('[data-document-select]');if(!select)continue;select.selectedIndex=0;select.dispatchEvent(new Event('change',{bubbles:true}));for(const key of ['actor','reason']){const e=host.querySelector('[data-document-'+key+']');e.value='';e.dispatchEvent(new Event('input',{bubbles:true}));}}};
 if(!value||!Array.isArray(value.forms)||value.forms.length!==formIds.length||!Array.isArray(value.documents)||value.documents.length>500)throw Error('Invalid recovery draft fields.');
 const seen=new Set(),forms=value.forms.map(row=>{if(!row||!formIds.includes(row.id)||seen.has(row.id)||!Array.isArray(row.fields))throw Error('Unknown recovery form.');seen.add(row.id);const form=$(row.id),fields=new Set(),rowFields=[...row.fields];if(older&&row.id==='timeline-review')for(const kind of ['complaintSent','documentsReceived','reply']){const name='serviceSource-'+kind;if(!rowFields.some(f=>f.name===name))rowFields.push({name,value:''});}if(rowFields.length!==[...form.elements].filter(e=>e.name&&['INPUT','SELECT'].includes(e.tagName)&&e.type!=='file').length)throw Error('Recovery form fields are incomplete.');return{id:row.id,fields:rowFields.map(f=>{const e=form.elements.namedItem(f.name);if(!e||!['INPUT','SELECT'].includes(e.tagName)||e.type==='file'||fields.has(f.name))throw Error('Unknown draft field.');fields.add(f.name);if(e.type==='checkbox'){if(typeof f.value!=='boolean')throw Error('Invalid draft checkbox.');}else if(typeof f.value!=='string'||f.value.length>20000||e.maxLength>0&&f.value.length>e.maxLength)throw Error('Invalid draft text.');if(e.name.startsWith('serviceSource-')&&f.value&&!timeline.events.some(v=>v.id===f.value&&v.kind===e.name.slice(14)&&v.status==='done'))throw Error('Unknown service source draft.');if(e.tagName==='SELECT'&&f.value&&!['key','id'].includes(e.name)&&!e.name.startsWith('serviceSource-')&&![...e.options].some(o=>o.value===f.value))throw Error('Unknown draft option.');if(e.name==='key'&&f.value&&!window.NavigatorTimeline.fields.includes(f.value))throw Error('Unknown milestone draft.');return{name:f.name,value:f.value};})};});
 const allowed=new Map();for(const e of workflow.documentTrail){const phases=window.PoshWorkflowDocuments.phasesForStage(e.stage,e.answer);allowed.set('g-context-docs-'+e.stage,phases[e.phase].ids);for(let i=0;i<e.phase;i++)allowed.set('g-context-earlier-'+e.stage+'-'+i,phases[i].ids);}
 const docsSeen=new Set(),documents=value.documents.map(row=>{if(!row||!allowed.get(row.id)?.includes(row.selection)||docsSeen.has(row.id)||typeof row.actor!=='string'||row.actor.length>100||typeof row.reason!=='string'||row.reason.length>250)throw Error('Invalid document draft fields.');docsSeen.add(row.id);return{id:row.id,selection:row.selection,actor:row.actor,reason:row.reason};});
 if(documents.length!==allowed.size)throw Error('Recovery document fields are incomplete.');
 return()=>{for(const row of forms)for(const f of row.fields){const e=$(row.id).elements.namedItem(f.name);if(e.type==='checkbox')e.checked=f.value;else e.value=f.value;}const stale=window.NavigatorTimeline.staleReviews(timeline);for(const key of ['commencementVerified','serviceReviewVerified'])if(stale[key])$('timeline-review').elements[key].checked=false;for(const row of documents){const host=$(row.id);if(!host)throw Error('Document draft could not be restored.');const select=host.querySelector('[data-document-select]');select.value=row.selection;select.dispatchEvent(new Event('change',{bubbles:true}));for(const [key,attr]of [['actor','actor'],['reason','reason']]){const e=host.querySelector('[data-document-'+attr+']');e.value=row[key];e.dispatchEvent(new Event('input',{bubbles:true}));}}};
}
function prepare(data){let workflow=data?.workflow,timeline=data?.timeline,legacy=false;if(data?.version===1&&Array.isArray(data.audit)){legacy=true;timeline=data;workflow={answers:{},decisions:{},documentTrail:[],status:'',chosenAction:'',checked:[],workSteps:[],uncertainSteps:[],followupDetail:'',lastKey:'',scenario:'manual'};}else if(data?.format!=='posh-navigator-session'||![1,2,3,4].includes(data.schemaVersion))throw Error('Unsupported recovery format.');if(!legacy&&data.schemaVersion<4&&timeline?.serviceEvents)throw Error('Service-source recovery requires format 4.');const applyWorkflow=W.prepare(workflow),applyTimeline=T.prepareRestore(timeline),applyDrafts=prepareDrafts(legacy||data.schemaVersion===1?undefined:data.drafts,workflow,timeline,legacy||data.schemaVersion<4);const applyEvidence=window.NavigatorEvidenceUI.prepareRestore(!legacy&&data.schemaVersion>=3?data.evidence:undefined);if(!legacy&&data.schemaVersion>=3&&!data.evidence)throw Error('Recovery evidence index is missing.');if(!legacy&&data.schemaVersion>=2&&!data.drafts)throw Error('Recovery draft fields are missing.');return{legacy,workflow,timeline,evidenceCount:!legacy&&data.schemaVersion>=3?data.evidence.record.items.length:0,apply:()=>{applyWorkflow();applyTimeline();applyDrafts();applyEvidence();}};}
async function read(file){if(!file||file.size>MAX_BYTES)throw Error('Choose a Navigator JSON file smaller than 2 MB.');const data=JSON.parse(await file.text());return{data,prepared:prepare(data)};}
function makeExport(){const value=snapshot(),text=JSON.stringify({...value,exportedAt:new Date().toISOString()},null,2);if(new Blob([text]).size>MAX_BYTES||value.timeline.audit.length>5000)throw Error('This session exceeds the recovery limit. Keep this tab open and export its timeline/history separately for institutional custody; contact support without sharing case information.');prepare(JSON.parse(text));return{value,text};}
function browserDownload(){try{const {text}=makeExport();if(downloadURL)URL.revokeObjectURL(downloadURL);downloadURL=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=$('session-download-link');a.href=downloadURL;a.download='POSH-Navigator-Recovery-'+new Date().toISOString().slice(0,10)+'.json';a.hidden=false;$('session-file-options').open=true;downloadRequested=true;a.click();message('Download requested. Check the completed file below before closing this tab.',false);status();}catch(e){message('Recovery file was not created: '+e.message);}}
async function save(){if(busy)return;busy=true;$('session-save').disabled=true;let writable,writeAttempted=false;try{const {value,text}=makeExport();if(typeof window.showSaveFilePicker!=='function'){browserDownload();return;}const handle=await window.showSaveFilePicker({suggestedName:'POSH-Navigator-Recovery-'+new Date().toISOString().slice(0,10)+'.json',types:[{description:'Navigator recovery file',accept:{'application/json':['.json']}}]});writable=await handle.createWritable();writeAttempted=true;await writable.write(text);await writable.close();writable=null;const file=await handle.getFile();if(await file.text()!==text)throw Error('The written file did not pass its read-back check.');await read(file);localHandle=handle;lastFileText=text;$('session-auto-save').disabled=false;markSaved(value,file.name);message('Saved and verified. Keep this recovery file securely and use Resume from a file next time.',false);}catch(e){if(writable)await writable.abort().catch(()=>{});if(writeAttempted){saved='';baseline='';verifiedName='';stopAuto(true);}message(e.name==='AbortError'?'Save cancelled. No new saved copy was verified. Keep this tab open unless its current work is already in a checked file.':'Save was not verified. Keep this tab open. '+e.message+' You can use the alternative browser download and check its saved file below.');}finally{busy=false;$('session-save').disabled=false;status();}}
async function updateLocalFile(){if(!localHandle||!$('session-auto-save').checked||!dirty()||busy||autoSaving)return;autoSaving=true;busy=true;$('session-save').disabled=true;let writable;try{const fileBefore=await localHandle.getFile();if(await fileBefore.text()!==lastFileText)throw Error('The recovery file changed outside this tab. Save to a new file to avoid overwriting another version.');const {value,text}=makeExport();writable=await localHandle.createWritable({mode:'exclusive'});if(await (await localHandle.getFile()).text()!==lastFileText)throw Error('The file changed before its update lock was acquired. Save to a new file.');await writable.write(text);await writable.close();writable=null;const file=await localHandle.getFile();if(await file.text()!==text)throw Error('The updated file failed its read-back check.');await read(file);lastFileText=text;markSaved(value,file.name);}catch(e){if(writable)await writable.abort().catch(()=>{});stopAuto(true);message('Automatic local save stopped. Keep this tab open and save a new verified recovery file. '+e.message);}finally{busy=false;autoSaving=false;$('session-save').disabled=false;status();}}
$('session-auto-save').onchange=()=>{if($('session-auto-save').checked&&!localHandle){stopAuto();message('Save and verify a local file first.');return;}message($('session-auto-save').checked?'Local file updates enabled every fifteen seconds while this tab is open. Wait for the saved status before closing. Updates stop on restore, restart, scenario replacement or a file error.':'Local file updates stopped. Save manually before leaving.',false);};
setInterval(updateLocalFile,15000);
let reviewURL='',reviewSnapshot='';function reviewKey(){return JSON.stringify({value:snapshot(),unsaved:dirty(),day:window.NavigatorTimeline.indiaDay()});}function currentReview(){const {value}=makeExport();return window.NavigatorSessionReview.build(value,T.getResult(),window.PoshWorkflowDocuments.entries,{step:document.getElementById('g-current')?.textContent||'Current step',kind:document.body.hasAttribute('data-account-required')&&value.workflow.scenario==='manual'?'Private procedural session':'Synthetic learning session',unsaved:dirty()});}
$('session-review-refresh').onclick=()=>{try{const host=$('session-review-content');host.innerHTML=window.NavigatorSessionReview.fragment(currentReview());reviewSnapshot=reviewKey();host.tabIndex=-1;host.focus();}catch(e){message('Session review could not be prepared. Your work remains in this tab. '+e.message);}};
$('session-review-dates').onclick=()=>{if(document.querySelector('.g-shell')?.inert){message('Verify account access before editing dates. You can still download a review of your existing local work.');return;}document.getElementById('g-step-dates')?.click();const all=document.getElementById('timeline-all');if(all?.getAttribute('aria-pressed')==='false')all.click();};
$('session-review-download').onclick=()=>{try{const sheet=window.NavigatorSessionReview.html(currentReview());if(reviewURL)URL.revokeObjectURL(reviewURL);reviewURL=URL.createObjectURL(new Blob([sheet],{type:'text/html'}));const a=document.createElement('a');a.href=reviewURL;a.download='POSH-Navigator-Session-Review-'+new Date().toISOString().slice(0,10)+'.html';a.click();message('Review sheet download requested. It is a readable local summary, not a recovery file or legal report. Save and verify your recovery file separately before closing.',false);}catch(e){message('Session review was not downloaded. '+e.message);}};
$('session-save').onclick=save;$('session-download').onclick=browserDownload;window.NavigatorSessionExperience={save,hasUnsavedChanges:dirty,cancelReplacement,updateLocalFile};
$('session-verify-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const {data}=await read(file);if(![3,4].includes(data.schemaVersion)||JSON.stringify({format:data.format,schemaVersion:data.schemaVersion,workflow:data.workflow,timeline:data.timeline,drafts:data.drafts,evidence:data.evidence})!==JSON.stringify(snapshot()))throw Error('This file does not contain all current work. Save a new recovery file before closing.');markSaved(snapshot(),file.name);message('Saved file verified. You can close this tab and resume from this file.',false);}catch(e){message('Saved copy was not verified: '+e.message);}finally{e.target.value='';}};
$('session-restore-open').onclick=()=>{$('session-restore-panel').hidden=false;$('session-file').focus();};
$('session-ready').onclick=()=>{$('session-onboarding').open=false;const body=$('g-body');body.setAttribute('tabindex','-1');body.focus();body.scrollIntoView({block:'start'});};
function cancel(){restoreGeneration++;pending=null;$('session-file').value='';$('session-restore-confirm').hidden=true;$('session-restore-panel').hidden=true;$('session-restore-preview').textContent='';}
$('session-restore-cancel').onclick=cancel;
$('session-file').onchange=async e=>{const generation=++restoreGeneration;pending=null;$('session-restore-confirm').hidden=true;$('session-error').hidden=true;try{const file=e.target.files[0];if(!file)return;const {prepared}=await read(file);if(generation!==restoreGeneration)return;pending={...prepared,name:file.name};$('session-restore-preview').textContent=(prepared.legacy?'Timeline-only export: questions restart at complaint intake. ':'Full session: '+Object.keys(prepared.workflow.answers).length+' recorded answers and '+prepared.workflow.documentTrail.length+' document steps. ')+prepared.timeline.events.length+' timeline events and '+prepared.evidenceCount+' evidence references. Restoring replaces this tab, including its current evidence index;  save current work first. Imported dates and decisions remain unverified.';$('session-restore-confirm').hidden=false;}catch(e){if(generation!==restoreGeneration)return;message('Restore was not applied: '+e.message);$('session-restore-preview').textContent='Your current session is unchanged.';}};
let priorScenario=$('g-scenario').value;
$('session-restore-confirm').onclick=()=>{if(!pending)return;const old=snapshot(),restoring=pending;cancelReplacement();try{stopAuto(true);restoring.apply();priorScenario=$('g-scenario').value;cancel();saved='';baseline='';verifiedName='';downloadRequested=false;message('Restored locally. Unsubmitted entries remain drafts. Verify imported choices, dates and history against institutional records, then save and check a fresh recovery file.',false);status();window.dispatchEvent(new Event('navigator:session-restored'));}catch(e){try{prepare(old).apply();}catch{}pending=null;$('session-restore-confirm').hidden=true;message('Restore could not finish and was rolled back. Keep this tab open. '+e.message);}};
window.addEventListener('beforeunload',e=>{if(dirty()){e.preventDefault();e.returnValue='';}});
let pendingReplacement=null,bypassReplacement=false,replacementFocus=null;
function cancelReplacement(){pendingReplacement=null;$('session-replace-panel').hidden=true;}
function askReplacement(description,action,focus){pendingReplacement=action;replacementFocus=focus;$('session-replace-description').textContent=description;$('session-replace-panel').hidden=false;$('session-replace-title').focus();$('session-replace-panel').scrollIntoView({block:'nearest'});}
$('session-replace-save').onclick=save;
$('session-replace-cancel').onclick=()=>{cancelReplacement();replacementFocus?.focus();};
$('session-replace-confirm').onclick=()=>{const action=pendingReplacement;cancelReplacement();stopAuto(true);if(!action)return;bypassReplacement=true;try{action();}finally{bypassReplacement=false;}};
document.addEventListener('change',e=>{if(e.target.id!=='g-scenario')return;const next=e.target.value;stopAuto(true);if(bypassReplacement){priorScenario=next;return;}e.target.value=priorScenario;const priorWork=dirty();if(priorWork){e.stopImmediatePropagation();askReplacement('Switching to a learning scenario clears the current workflow answers and document progress.',()=>{e.target.value=next;priorScenario=next;e.target.dispatchEvent(new Event('change',{bubbles:true}));},e.target);return;}priorScenario=next;e.target.value=next;},true);
document.addEventListener('click',e=>{if(['g-restart','g-reset-inline'].includes(e.target.id))stopAuto(true);if(!['g-restart','g-reset-inline'].includes(e.target.id)||bypassReplacement||!dirty())return;e.preventDefault();e.stopImmediatePropagation();const id=e.target.id;askReplacement('Starting over clears the current workflow answers and document progress.',()=>{const target=document.getElementById(id);if(target)target.click();else message('The current step changed. Your work was kept; choose the restart action again.');},e.target);},true);

document.addEventListener('input',status);document.addEventListener('click',()=>requestAnimationFrame(status));window.addEventListener('navigator:timeline-changed',status);setInterval(status,2000);status();
})();